#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        int temp;
        cin >> temp;
        a[i] = temp % m;
    }

    set<int> set_a, set_b;

    function<void(set<int>&, int, int, int)> create_subsets = [&](set<int>& subset_container, int length, int start_idx, int total=0) {
        if (start_idx == length) {
            subset_container.insert(total);
        } else {
            create_subsets(subset_container, length, start_idx + 1, (total + a[start_idx]) % m);
            create_subsets(subset_container, length, start_idx + 1, total);
        }
    };

    int mid_point = n / 2;
    create_subsets(set_a, mid_point, 0);
    create_subsets(set_b, n, mid_point);

    vector<int> sorted_b(set_b.begin(), set_b.end());
    sort(sorted_b.begin(), sorted_b.end());

    int max_value = 0;
    for (auto val : set_a) {
        int pos = (int)(std::lower_bound(sorted_b.begin(), sorted_b.end(), m - val) - sorted_b.begin());
        if (pos > 0) {
            int sum_candidate = val + sorted_b[pos - 1];
            if (sum_candidate > max_value) {
                max_value = sum_candidate;
            }
        }
    }
    cout << max_value << "\n";
    return 0;
}
